import pandas as pd
from pandas import DatetimeIndex, Timestamp
from pandas.tseries.offsets import YearEnd, QuarterEnd, YearBegin, BYearEnd, HalfYearEnd

x = "1970-06-15"
dti = DatetimeIndex([x])
off = YearEnd(2**62)

out = {}

def run_index(offset):
    try:
        r = dti + offset
        return {"ok": True, "value": str(list(r.astype(str)))}
    except Exception as e:
        return {"ok": False, "exc": type(e).__name__, "msg": str(e)}

def run_scalar(offset):
    try:
        r = dti[0] + offset
        return {"ok": True, "value": str(r)}
    except Exception as e:
        return {"ok": False, "exc": type(e).__name__, "msg": str(e)}

out['index_YearEnd_2_62'] = run_index(off)
out['scalar_YearEnd_2_62'] = run_scalar(off)

# Also cover an additional offset class mentioned in the strategy.
o2 = QuarterEnd(2**62)
out['index_QuarterEnd_2_62'] = run_index(o2)
out['scalar_QuarterEnd_2_62'] = run_scalar(o2)

# Control: representable shift should not raise (YearEnd(2)).
o3 = YearEnd(2)
out['index_YearEnd_2'] = run_index(o3)
out['scalar_YearEnd_2'] = run_scalar(o3)

# NaT all-path behavior (should not raise; return all NaT).
dti_nat = DatetimeIndex([pd.NaT, pd.NaT])

def run_index_nat(offset):
    try:
        r = dti_nat + offset
        return {"ok": True, "value": str(list(r.astype(str)))}
    except Exception as e:
        return {"ok": False, "exc": type(e).__name__, "msg": str(e)}

out['index_all_nat_YearEnd_2_62'] = run_index_nat(off)

probe(out)

